 "new_string": "def transform(grid):
    h, w = len(grid), len(grid[0])
    background = Counter(v for row in grid for v in row).most_common(1)[0][0]

    # Horizontal lattice lines are rows mostly filled with a non-background line color.
    separators = []
    for r, row in enumerate(grid):
        counts = Counter(row)
        color, count = counts.most_common(1)[0]
        if color != background and count >= 0.7 * w:
            separators.append((r, color))
    if len(separators) < 2:
        return [[background]]

    # Keep the run of lattice intersections containing colored markers.
    marker_cols = sorted({c for r, line_color in separators
                          for c, value in enumerate(grid[r])
                          if value != line_color})
    if len(marker_cols) < 2:
        return [[background]]
    left, right = marker_cols[0], marker_cols[-1]
    node_cols = [c for c in range(left, right + 1)
                 if any(grid[r][c] != line_color for r, line_color in separators)]
    if len(node_cols) < 2:
        return [[background]]

    # A decoded pixel is colored only when all four corner markers agree.
    node_rows = []
    for r, line_color in separators:
        node_rows.append([background if grid[r][c] == line_color else grid[r][c]
                          for c in node_cols])
    out = []
    for ri in range(len(node_rows) - 1):
        row = []
        for ci in range(len(node_cols) - 1):
            corners = (node_rows[ri][ci], node_rows[ri][ci + 1],
                       node_rows[ri + 1][ci], node_rows[ri + 1][ci + 1])
            value = corners[0] if corners[0] != background and len(set(corners)) == 1 else background
            row.append(value)
        out.append(row)
    return out",
